text:
{
  "claims": [
    {
      "anchor": "enable AOF on the live server with CONFIG SET appendonly yes",
      "claim_text": "To switch a running server from RDB to AOF, enable AOF on the live server with CONFIG SET appendonly yes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P1.S0", "rel": "entails", "sub": "Enable AOF: `redis-cli config set appendonly yes`"}
      ],
      "check": null,
      "reasoning": "Passage 0 says enable AOF via CONFIG on live server; Passage 1 gives the command."
    },
    {
      "anchor": "also update redis.conf",
      "claim_text": "To switch from RDB to AOF, you must also update redis.conf.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails", "sub": "Update your `redis.conf`"}
      ],
      "check": null,
      "reasoning": "Passage 1 says update redis.conf and ensure it matches."
    },
    {
      "anchor": "otherwise the change is lost when the server restarts",
      "claim_text": "If you do not update redis.conf, the configuration changes are lost when the server restarts.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails", "sub": "when you restart the server, the configuration changes will be lost"}
      ],
      "check": null,
      "reasoning": "Passage 1 states forgetting this step loses changes on restart."
    },
    {
      "anchor": "Redis automatically blocks incoming writes while it converts the dataset",
      "claim_text": "Redis automatically blocks incoming writes while it converts the dataset from RDB to AOF.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage says Redis blocks writes during conversion."
    },
    {
      "anchor": "Before restarting, wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0",
      "claim_text": "Before restarting, wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"},
        {"sid": "P2.S1", "rel": "entails", "sub": "waiting for `aof_rewrite_in_progress` and `aof_rewrite_scheduled` to be `0`"}
      ],
      "check": null,
      "reasoning": "Passage 2 says wait for rewrite to finish and both fields to be 0."
    },
    {
      "anchor": "On Redis 7.0 or later, an AOF-only instance can be backed up by copying the files in the directory set by the appendfilename option",
      "claim_text": "On Redis 7.0 or later, an AOF-only instance can be backed up by copying the files in the directory set by the appendfilename option.",
      "kind": "direct",
      "sure": false,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"},
        {"sid": "P4.S1", "rel": "entails", "sub": "Since Redis 7.0.0, AOF files are split into multiple files which reside in a single directory determined by the `appenddirname` configuration."},
        {"sid": "P4.S2", "rel": "entails", "sub": "copy/tar the files in this directory"}
      ],
      "check": {"kind": "version", "left": "7.0", "op": ">=", "right": "7.0.0"},
      "reasoning": "Passages say appenddirname, not appendfilename; claim names wrong option."
    },
    {
      "anchor": "copying them while a rewrite is running is safe",
      "claim_text": "Copying AOF files while a rewrite is running is safe.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S3", "rel": "refutes", "sub": "if this is done during a [rewrite](#log-rewriting), you might end up with an invalid backup"}
      ],
      "check": null,
      "reasoning": "Passage 4 says copying during rewrite may yield invalid backup."
    },
    {
      "anchor": "set auto-aof-rewrite-percentage to 0, which turns off automatic rewrites",
      "claim_text": "Setting auto-aof-rewrite-percentage to 0 turns off automatic rewrites.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S1", "rel": "entails", "sub": "Turn off automatic rewrites with<br/> `CONFIG SET` `auto-aof-rewrite-percentage 0`"}
      ],
      "check": null,
      "reasoning": "Passage 5 states this command turns off automatic rewrites."
    },
    {
      "anchor": "If you take hard links to those files, you can re-enable rewrites before the copy finishes",
      "claim_text": "If you take hard links to the AOF files, you can re-enable rewrites before the copy finishes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails", "sub": "create hard links to the files in `appenddirname` (in step 3 above) and then re-enable rewrites (step 4) after the hard links are created."},
        {"sid": "P6.S1", "rel": "entails", "sub": "Now you can copy/tar the hardlinks"}
      ],
      "check": null,
      "reasoning": "Passage 6 says create hard links, re-enable rewrites, then copy hardlinks."
    },
    {
      "anchor": "because Redis only appends to files in that directory or completely replaces them",
      "claim_text": "Redis only appends to files in the appenddirname directory or completely replaces them.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails", "sub": "Redis guarantees that it only appends to files in this directory, or completely replaces them if necessary"}
      ],
      "check": null,
      "reasoning": "Passage 6 states this guarantee."
    },
    {
      "anchor": "On Redis 6.0, backing up the AOF is as simple as copying the aof file",
      "claim_text": "On Redis 6.0, backing up the AOF is as simple as copying the aof file.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails", "sub": "Prior to version 7.0.0 backing up the AOF file can be done simply by copying the aof file"}
      ],
      "check": {"kind": "version", "left": "6.0", "op": "<", "right": "7.0.0"},
      "reasoning": "Passage 7 says prior to 7.0.0, copying the aof file suffices."
    },
    {
      "anchor": "Redis can still load the copy even if it lacks the final part",
      "claim_text": "Redis can still load a copied AOF file even if it lacks the final part.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails", "sub": "The file may lack the final part but Redis will still be able to load it"}
      ],
      "check": null,
      "reasoning": "Passage 7 states Redis can load a truncated AOF."
    }
  ]
}
